from sympy.ntheory.modular import crt
import gmpy2
from Crypto.Util.number import long_to_bytes

def parse_values(filename):
    ns = []
    cs = []
    e = 0

    with open(filename, 'r') as f:
        lines = f.readlines()
        for line in lines:
            if line.startswith('n'):
                ns.append(int(line.split(':')[1].strip()))
            elif line.startswith('c'):
                cs.append(int(line.split(':')[1].strip()))
            elif line.startswith('e'):
                e = int(line.split(':')[1].strip())

    return ns, cs, e

def solve_hastad(ns, cs, e):
    # Use CRT to combine congruences
    result = crt(ns, cs)[0]

    # Take eth root
    m, is_perfect = gmpy2.iroot(result, e)
    if not is_perfect:
        print("Warning: root is not perfect")
    return int(m)

def int_to_string(m):
    try:
        # Convert to bytes and decode
        return bytes.fromhex(hex(m)[2:]).decode('utf-8')
    except Exception as e:
        print(f"Error decoding: {e}")
        return None

def main():
    ns, cs, e = parse_values('/home/ctfplayer/ctf_files/values.txt')
    print(f"Found {len(ns)} moduli and {len(cs)} ciphertexts with e={e}")

    m = solve_hastad(ns, cs, e)
    password = int_to_string(m)
    print(f"Recovered password: {password}")

if __name__ == '__main__':
    main()

from cryptography.fernet import Fernet
import base64

def get_key(password):
    # Try different methods to create a valid Fernet key

    # 1. Pad/truncate to 32 bytes then base64
    try:
        key = password.encode().ljust(32, b'\0')[:32]
        return base64.urlsafe_b64encode(key)
    except:
        print("Method 1 failed")
        pass

    # 2. Direct base64 encoding of password
    try:
        return base64.urlsafe_b64encode(password.encode())
    except:
        print("Method 2 failed")
        pass

    # 3. If password is hex, decode first
    try:
        return base64.urlsafe_b64encode(bytes.fromhex(password))
    except:
        print("Method 3 failed")
        pass

def try_decrypt(key, encrypted):
    try:
        f = Fernet(key)
        decrypted = f.decrypt(encrypted.encode())
        print(f"Successfully decrypted: {decrypted.decode()}")
        return decrypted.decode()
    except Exception as e:
        print(f"Decryption failed: {str(e)}")
        return None

